<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Horarios — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033}.wrap{max-width:920px;margin:auto;padding:78px 12px 32px}h1{margin:0 0 4px}.sub{color:#64748b;font-size:13px;margin-bottom:18px}.actions{display:flex;justify-content:flex-end;margin-bottom:12px}.btn{border:0;border-radius:10px;padding:10px 13px;font-weight:800;cursor:pointer}.btn-primary{background:#172033;color:#fff}.grid{display:grid;gap:10px}.card{background:#fff;border-radius:14px;padding:13px;display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center}.hora{font-size:19px;font-weight:900}.meta{font-size:12px;color:#64748b;margin-top:4px}.tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.tag{font-size:10px;font-weight:800;border-radius:999px;padding:4px 7px;background:#e8eef2}.off{opacity:.55}.mini{border:0;border-radius:8px;padding:8px 9px;font-weight:800;cursor:pointer}.modal{display:none;position:fixed;inset:0;background:#0006;z-index:3000;align-items:center;justify-content:center;padding:16px}.modal.open{display:flex}.box{width:min(430px,100%);background:#fff;border-radius:16px;padding:18px}.box h2{margin:0 0 14px}.field{margin-bottom:12px}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:5px}.field input{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:9px;font-size:16px}.checks{display:flex;gap:14px;margin:12px 0}.modal-actions{display:flex;gap:8px;justify-content:flex-end}.empty{text-align:center;color:#64748b;padding:30px}@media(min-width:760px){.wrap{padding-top:35px}.grid{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><h1>Horarios</h1><div class="sub">Clases regulares e intensivos</div><div class="actions"><button id="nuevo" class="btn btn-primary">+ Nuevo horario</button></div><div id="lista" class="grid"><div class="empty">Cargando…</div></div></main><div id="modal" class="modal"><div class="box"><h2>Nuevo horario</h2><div class="field"><label>Hora inicio</label><input id="ini" type="time"></div><div class="field"><label>Hora fin</label><input id="fin" type="time"></div><div class="checks"><label><input id="regular" type="checkbox" checked> Regular</label><label><input id="intensivo" type="checkbox"> Intensivo</label></div><div class="modal-actions"><button id="cerrar" class="btn">Cancelar</button><button id="guardar" class="btn btn-primary">Guardar</button></div></div></div><script>const lista=document.getElementById('lista'),modal=document.getElementById('modal');async function api(body){const r=await fetch('/api/horarios.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}function h(v){return String(v||'').slice(0,5)}async function cargar(){const r=await fetch('/api/horarios.php'),d=await r.json();if(!d.ok){lista.innerHTML='<div class="empty">Error al cargar.</div>';return}lista.innerHTML=d.horarios.length?d.horarios.map(x=>`<article class="card ${x.activo==1?'':'off'}"><div><div class="hora">${h(x.hora_inicio)}–${h(x.hora_fin)}</div><div class="meta">${x.alumnos_regulares} regulares · ${x.alumnos_intensivo} intensivo</div><div class="tags">${x.regular==1?'<span class="tag">REGULAR</span>':''}${x.intensivo==1?'<span class="tag">INTENSIVO</span>':''}${x.activo==1?'':'<span class="tag">INACTIVO</span>'}</div></div><button class="mini" data-id="${x.id}" data-r="${x.regular}" data-i="${x.intensivo}" data-a="${x.activo}">${x.activo==1?'Editar':'Activar'}</button></article>`).join(''):'<div class="empty">No hay horarios.</div>'}document.getElementById('nuevo').onclick=()=>modal.classList.add('open');document.getElementById('cerrar').onclick=()=>modal.classList.remove('open');document.getElementById('guardar').onclick=async()=>{try{await api({accion:'CREAR',hora_inicio:ini.value,hora_fin:fin.value,regular:regular.checked,intensivo:intensivo.checked});modal.classList.remove('open');ini.value='';fin.value='';cargar()}catch(e){alert(e.message)}};lista.onclick=async e=>{const b=e.target.closest('[data-id]');if(!b)return;const activo=b.dataset.a==='1';const r=b.dataset.r==='1',i=b.dataset.i==='1';const nr=confirm('¿Este horario se usa para clases regulares?')?1:0;const ni=confirm('¿Este horario se usa para intensivos?')?1:0;if(!nr&&!ni){alert('Debe quedar habilitado al menos para un tipo.');return}try{await api({accion:'ACTUALIZAR',id:b.dataset.id,regular:nr,intensivo:ni,activo:activo?confirm('Aceptar = mantener activo. Cancelar = desactivar.')?1:0:1});cargar()}catch(err){alert(err.message)}};cargar();</script></body></html>